"""Close the matched transfer experiment after direct output review; no model execution."""
import hashlib,json
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parent;PROJECT=ROOT.parents[1];PRIVATE=ROOT/'private'
def read(p):return json.loads(Path(p).read_text())
def save(p,x):Path(p).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
def main():
 r=read(ROOT/'result.json');assert r['status']=='BOUNDED_MATCHED_EXPERIMENT_COMPLETE_PENDING_DIRECT_REVIEW'
 assert not (ROOT/'STOP.json').exists() and r['updates_consumed_total']==400
 assert r['sft_target_exposures_total']==152642 and r['narrative_replay_target_exposures_total']==819200
 arms=r['arms'];assert all(a['updates_consumed']==200 and a['sft_targets_consumed']==76321 and a['replay_targets_consumed']==409600 for a in arms.values())
 schedules=read(PRIVATE/'schedules.json');assert Counter(i for b in schedules['curriculum'] for i in b)==Counter(i for b in schedules['shuffled_control'] for i in b)
 accepted={'curriculum':{('t-clarify-0',0)},'shuffled_control':{('t-clarify-0',0),('t-change-3-1',1)}}
 summary={};reviews={}
 for name,a in arms.items():
  rows=read(PRIVATE/(name+'-final-test-responses.json'));assert len(rows)==48
  actual={(x['id'],x['turn']) for x in rows if x['correct'] and x['eos']};assert actual==accepted[name]
  assert a['test']['counterfactual_pairs_correct']==0 and not a['pilot_progress_pass']
  assert a['selected']['updates']==175 and a['selected']['foundation_regression_fraction']<=.05
  # All 96 final outputs were directly inspected. No scoring rules are changed after inspection.
  reviews[name]=dict(directly_inspected=48,confirmed_full_compliance=len(actual),accepted=[dict(id=i,turn=t) for i,t in sorted(actual)],finding='Most outputs remain nonsensical or fail to extract supplied facts. The correct clarification is near-transfer of a trained question. One control correction turn matches the supplied owner but its complete conversation fails.',partial_examples=[dict(id=x['id'],turn=x['turn'],response=x['response']) for x in rows if name=='curriculum' and x['id'] in ['t-missing-0','t-missing-3']],partial_interpretation='These two curriculum outputs broadly indicate missing information but violate the explicit Unknown-only format; they remain failures under the frozen rule.')
  clean=[x for x in rows if x['id']!='t-color-2-1']
  summary[name]=dict(updates_consumed=a['updates_consumed'],sft_targets_consumed=a['sft_targets_consumed'],replay_targets_consumed=a['replay_targets_consumed'],selected_updates=a['selected']['updates'],selected_sft_targets=a['selected']['sft_targets'],selected_replay_targets=a['selected']['replay_targets'],correct_and_eos=a['test']['correct_and_eos_turns'],turns=48,eos=a['test']['eos_turns'],counterfactual_pairs_correct=0,counterfactual_pairs=16,foundation_regression_fraction=a['selected']['foundation_regression_fraction'],development_nll=a['selected']['dev_nll'],test_nll=a['test_nll'],pilot_progress_pass=False,checkpoint=a['selected']['checkpoint'],checkpoint_sha256=a['selected']['checkpoint_sha256'],article_defect_sensitivity=dict(excluded_one_case=True,correct=sum(x['correct'] and x['eos'] for x in clean),turns=47))
 save(PRIVATE/'direct-review.json',dict(reviewer='Primary assistant directly read all 48 paired final outputs, 96 complete responses',arms=reviews,benchmark_issue='One color prompt has an incorrect indefinite article; meaning is unambiguous. Frozen inputs and original counts are preserved. Excluding it leaves 1/47 and 2/47 correct. Removing its counterfactual pair leaves 0/15 paired successes in each arm.',rules_unchanged=True))
 for path,h in read(ROOT/'freeze.json')['files'].items():assert hashlib.sha256((PROJECT/path).read_bytes()).hexdigest()==h
 source=read(ROOT/'plan.json');assert hashlib.sha256((PROJECT/source['source_checkpoint']).read_bytes()).hexdigest()==source['source_sha256']
 decision=dict(status='TRANSFER_PROGRESS_GATES_FAILED_TRAINING_CLOSED',baseline_correct_and_eos=0,baseline_turns=48,baseline_eos=0,arms=summary,updates_consumed_total=400,sft_supervised_target_exposures_total=152642,narrative_replay_target_exposures_total=819200,total_student_positions=r['total_positions'],elapsed_seconds=r['elapsed_seconds'],source_unchanged=True,parameters=15191712,checkpoint_promoted=False,training_finished=True,training_paused=True,automatic_continuation=False,direct_response_reviews=96,scoring_rules_unchanged=True,conclusion='Stopping transfers to many unseen prompts, but reliable factual grounding and correction do not meet the pilot gates. One versus two successes is not evidence of a dependable curriculum advantage.',limitations=['One seed and a small self-authored synthetic suite; not an independent benchmark.','Attempted full schedules have matched exposures, but selected checkpoint prefixes have different SFT exposure multisets.','One minor article defect; leave the bank unchanged and report exclusion sensitivity.','Exact normalized value/format rules deliberately penalize long, invented or noncompliant answers; clarification requires a relevant single question.','Narrative validation is inherited fixed native TinyStories data, not a broad English capability test.'],next_target='A controlled variable-binding/copying curriculum with many distinct values and phrasings, with held-out combinations; further generic-dialogue scaling is not supported by this test.')
 save(ROOT/'decision.json',decision);save(ROOT/'execution-status.json',dict(status=decision['status'],all_training_finished=True,automatic_continuation=False,checkpoint_promoted=False,source_unchanged=True))
 lines=['# Short-answer transfer experiment — progression gates failed','',
 'Completed two separate 200-update runs from the same unchanged own 15,191,712-parameter foundation checkpoint. Short-answer-first and shuffled control used the same complete SFT batch multiset and the same narrative replay batches in the same step order. Neither passed the frozen pilot progression criteria. Training is closed; no checkpoint was promoted.','',
 '## Fresh test results','',
 '| Metric | Original source | Short-answer-first | Shuffled control |','|---|---:|---:|---:|','| Correct answer plus EOS | 0/48 | 1/48 | 2/48 |','| EOS emitted | 0/48 | 40/48 | 43/48 |','| Fully correct counterfactual pairs | 0/16 | 0/16 | 0/16 |',
 f"| Foundation NLL increase from original source | — | {summary['curriculum']['foundation_regression_fraction']:.2%} | {summary['shuffled_control']['foundation_regression_fraction']:.2%} |",'',
 'Pilot thresholds: at least16/48 correct+EOS, improvement of8 over baseline, at least44/48 EOS endings, at least4/16 counterfactual pairs, and narrative NLL within5% of the original reference. Both arms passed only the foundation-preservation gate. This was a pilot progress criterion, not a general conversation release gate.','',
 'The primary assistant directly inspected all96 final outputs. Grounded extraction and corrections mostly remained incoherent or invented. The shared success was a relevant destination-clarification question similar to a trained response. The control also answered one corrected-owner turn, but that complete conversation failed. Two curriculum replies acknowledged missing information in broad terms but violated the explicitly requested Unknown-only format; their scores were not changed.','',
 'One frozen color prompt contains a minor indefinite-article error. The meaning remains clear; excluding that case gives1/47 versus2/47, and excluding its paired group leaves0/15 paired successes. The original bank, metrics and timestamps are preserved.','',
 '## Data and design','',
 'Training: eight short reviewed examples plus62 directly reviewed GPT-6 Sol demonstrations (70 conversations,3,738 assistant content tokens,3,874 unique-position supervised targets including EOS). No new teacher calls or downloads. The curriculum used50 batches of the short examples followed by150 broader batches; the control shuffled those exact200 batches. Batch8, context256, fresh AdamW, LR5e-5 with five-update warmup, BF16 compute/FP32 weights and moments, clip1.','',
 'Each update optimized0.5 assistant/EOS-only cross-entropy and0.5 narrative cross-entropy, each normalized over its own active targets. Narrative replay used existing TinyStories training shard data43 only; its hash matches the original dataset receipt. No validation shard was used for training. Both arms replayed the same409,600 narrative positions in the same order;819,200 replay exposures were charged across the two separate models. These are position/exposure counts, not claims of unique text.','',
 'Development:12 fresh conversations/16 turns. Test:40 fresh conversations/48 turns, including16 paired fact-change checks. Banks were authored and inspected before execution, then frozen. Exact normalized user-prompt overlap is zero between train/development/test; this does not prove semantic independence. Test outputs were generated at baseline and once per selected arm after both training runs had finished. Test never selected a checkpoint. Probes are synthetic near-transfer checks, not a sealed independent benchmark.','',
 'Checkpoint selection: among epochs within5% narrative regression, maximize development correct+EOS turns, then EOS turns, then minimize development loss. Both selected update175. Full attempted exposure multisets match; retained175-update prefixes do not. A single1-versus2 result cannot establish a causal curriculum advantage.','',
 '## Accounting and guardrails','',
 f"Consumed across both models:400 updates,152,642 assistant/EOS target exposures,819,200 narrative replay exposures,{r['total_positions']:,} student positions including padding/evaluations, and{r['elapsed_seconds']:.2f} seconds of execution. Caps were400 total updates,30 minutes,5M positions,200k SFT targets,819,200 replay targets and5GiB new artifacts.",'',
 'Selected short-first child retains175 updates,64,073 SFT targets and358,400 replay targets. Selected control retains175 updates,66,839 SFT targets and358,400 replay targets. All discarded updates/exposures remain charged. All eight checkpoints per arm were within the5% foundation limit, although late checkpoints approached it. No guardrail was relaxed.','',
 'Correctness preflight passed independent Torch FP32/native BF16 loss and gradient comparison. Changing masked labels or right-padding inputs changed loss by zero. Parent weights, architecture and tokenizer remain unchanged. The earlier foundation-recovery D0/R1/R2 stop remains intact; this experiment admitted no new broad foundation corpus.','',
 '## Local evidence and next decision','',
 'Research child checkpoints: `curriculum/epoch-175.pt` and `shuffled_control/epoch-175.pt`. Private fresh banks, raw responses and detailed direct inspection are under `private/`; weights and evaluation plaintext remain outside Git. Aggregate metrics, code, freeze hashes and accounting are versioned.','',
 'Next useful target is controlled variable binding: varied short factual examples with disjoint held-out combinations and wordings. The current results support learned stopping on many new prompts, but do not establish reliable use of supplied facts. No larger training run or automatic continuation was launched.']
 (ROOT/'README.md').write_text('\n'.join(lines)+'\n');print(json.dumps(decision,indent=2))
if __name__=='__main__':main()
